import SwiftUI
import AppKit

/// Official Google Keep SVG Theme vector assets for both Light & Dark modes.
enum KeepThemeAssets {
    private static var imageCache: [String: NSImage] = [:]

    private static let rawLightBase64: [NoteTheme: String] = [
        .places: "",
        .food: "",
        .music: "",
        .grocery: "",
        .notes: "",
        .recipe: "",
        .travel: "",
        .video: "",
        .celebration: "",
    ]

    private static let rawDarkBase64: [NoteTheme: String] = [
        .places: "",
        .food: "",
        .music: "",
        .grocery: "",
        .notes: "",
        .recipe: "",
        .travel: "",
        .video: "",
        .celebration: "",
    ]

    /// Retrieves or decodes the vector SVG NSImage for a given theme matching light/dark appearance.
    static func nsImage(for theme: NoteTheme, isDark: Bool) -> NSImage? {
        if theme == .none { return nil }
        let cacheKey = "\(theme.rawValue)_\(isDark ? "dark" : "light")"
        if let cached = imageCache[cacheKey] {
            return cached
        }
        let b64 = isDark ? rawDarkBase64[theme] : rawLightBase64[theme]
        guard let b64Str = b64,
              let data = Data(base64Encoded: b64Str),
              let img = NSImage(data: data) else {
            return nil
        }
        imageCache[cacheKey] = img
        return img
    }

    /// Renders the official Google Keep SVG vector thumbnail for the theme picker.
    @ViewBuilder
    static func thumbnail(for theme: NoteTheme, isDark: Bool = false, size: CGFloat = 28) -> some View {
        if let img = nsImage(for: theme, isDark: isDark) {
            Image(nsImage: img)
                .resizable()
                .scaledToFill()
                .frame(width: size, height: size)
                .clipShape(Circle())
        } else {
            Circle()
                .fill(Color.primary.opacity(0.1))
                .frame(width: size, height: size)
        }
    }

    /// Full-bleed card background covering the whole note card Google Keep-style with dynamic Light/Dark SVGs.
    @ViewBuilder
    static func cardBackground(for theme: NoteTheme, customThemeId: String? = nil, color: NoteColor, isDark: Bool = false) -> some View {
        ZStack {
            // Base background layer
            if color != .default {
                color.background
            } else if theme != .none || customThemeId != nil {
                LinearGradient(
                    colors: theme.gradientColors.isEmpty ? [Color.primary.opacity(0.04), Color.primary.opacity(0.08)] : theme.gradientColors,
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
            } else {
                Color(nsColor: .windowBackgroundColor)
            }

            // Full-cover Google Keep vector illustration or Custom SVG
            if let customId = customThemeId, let img = CustomArtThemeManager.shared.nsImage(for: customId, isDark: isDark) {
                GeometryReader { geo in
                    Image(nsImage: img)
                        .resizable()
                        .scaledToFill()
                        .frame(width: geo.size.width, height: geo.size.height, alignment: .bottomTrailing)
                        .clipped()
                }
                .allowsHitTesting(false)
            } else if let img = nsImage(for: theme, isDark: isDark) {
                GeometryReader { geo in
                    Image(nsImage: img)
                        .resizable()
                        .scaledToFill()
                        .frame(width: geo.size.width, height: geo.size.height, alignment: .bottomTrailing)
                        .clipped()
                }
                .allowsHitTesting(false)
            }
        }
        .allowsHitTesting(false)
    }
}
